    'home.how.s1.desc': { en: 'Two minutes online: your service, your home and your preferred day. Photos are optional and help us be precise.', fr: 'Deux minutes en ligne : votre service, votre maison et votre journée préférée. Les photos sont facultatives et nous aident à être précis.' },
