    'home.how.direct': { en: 'Just need a standard cleaning? <a href="book.html">Book and pay online now &rarr;</a>', fr: 'Besoin d’un simple ménage standard ? <a href="book.html">Réservez et payez en ligne maintenant &rarr;</a>' },
