    'home.area.title': { en: 'Proudly serving three communities', fr: 'Fièrement au service de trois communautés' },
    'home.area.desc': { en: 'Based in Clarence-Rockland, cleaning homes across the region, into Ottawa, and across the river into Gatineau. If you’re nearby and not sure you’re covered, just ask.', fr: 'Basée à Clarence-Rockland, notre entreprise nettoie des maisons dans toute la région, jusqu’à Ottawa, et de l’autre côté de la rivière à Gatineau. Si vous êtes à proximité et pas certain d’être couvert, demandez-nous simplement.' },
    'home.area.mapTitle': { en: 'Map of the Magicstick Clean service area: Clarence-Rockland, Ottawa, and Gatineau', fr: 'Carte de la zone desservie par Magicstick Clean : Clarence-Rockland, Ottawa et Gatineau' },

    // ---------- index.html: FAQ ----------
    'home.faq.title': { en: 'Common questions', fr: 'Questions fréquentes' },
    'home.faq.subtitle': { en: 'If yours isn’t here, just ask when you request a quote.', fr: 'Si votre question n’est pas ici, posez-la simplement lors de votre demande de devis.' },
    'home.faq.q1': { en: 'How much does a cleaning cost?', fr: 'Combien coûte un nettoyage?' },
    'home.faq.a1': { en: 'It depends on the size of the space and how often you’d like visits. Starting prices for each service are listed above, and recurring visits come with a standing discount. You’ll always get a clear price before booking.', fr: 'Ça dépend de la taille de l’espace et de la fréquence des visites. Les prix de départ de chaque service sont indiqués ci-dessus, et les visites récurrentes bénéficient d’un rabais permanent. Vous obtenez toujours un prix clair avant de réserver.' },
    'home.faq.q2': { en: 'Do I need to be home during the cleaning?', fr: 'Dois-je être à la maison pendant le nettoyage?' },
    'home.faq.a2': { en: 'Not at all. Many clients are out at work. As long as we’ve arranged access ahead of time, everything else takes care of itself.', fr: 'Pas du tout. Plusieurs clients sont au travail. Tant que l’accès est arrangé à l’avance, tout le reste se fait tout seul.' },
    'home.faq.q3': { en: 'Do you bring your own supplies?', fr: 'Apportez-vous vos propres produits ?' },
    'home.faq.a3': { en: 'Yes, eco-friendly supplies and equipment are included at no extra cost. If you’d prefer we use products you already have, just let us know.', fr: 'Oui, les produits écologiques et l’équipement sont inclus sans frais supplémentaires. Si vous préférez que nous utilisions vos propres produits, dites-le-nous simplement.' },
    'home.faq.q4': { en: 'What if I’m not happy with the clean?', fr: 'Et si je ne suis pas satisfait du nettoyage?' },
    'home.faq.a4': { en: 'Tell us within 24 hours and we’ll come back to fix it, free of charge. Getting it right matters more than getting it done fast.', fr: 'Avise-nous dans les 24 heures et nous revenons corriger le tout, gratuitement. Bien faire les choses compte plus que les faire vite.' },
    'home.faq.q5': { en: 'Do you offer recurring cleanings?', fr: 'Offrez-vous des ménages réguliers ?' },
    'home.faq.a5': { en: 'Yes: weekly, biweekly or monthly. Pick a frequency in your quote request and your personalized price takes it into account.', fr: 'Oui : chaque semaine, aux deux semaines ou chaque mois. Choisissez une fréquence dans votre demande de devis et votre prix personnalisé en tient compte.' },
    'home.faq.q6': { en: 'What’s your cancellation policy?', fr: 'Quelle est votre politique d’annulation ?' },
    'home.faq.a6': { en: 'Plans change, that’s fine. Just give at least 24 hours notice where possible so the time can go to another client.', fr: 'Les plans changent, c’est correct. Donnez simplement un préavis d’au moins 24 heures si possible, pour que la plage horaire puisse être offerte à un autre client.' },
    'home.faq.q7': { en: 'Do you clean around pets?', fr: 'Faites-vous le ménage en présence d’animaux ?' },
    'home.faq.a7': { en: 'Of course. Just let us know what pets are home so we can plan around them. For everyone’s safety, aggressive or very anxious pets are best kept in another room during the visit.', fr: 'Bien sûr. Dites-nous simplement quels animaux sont à la maison pour que nous puissions nous organiser. Pour la sécurité de tous, les animaux agressifs ou très anxieux sont mieux gardés dans une autre pièce pendant la visite.' },

