    'contest.how.s2.desc': { en: '50 entries are drawn at random among all eligible entries received by December 31, 2026.', fr: '50 inscriptions sont tirées au hasard parmi toutes les inscriptions admissibles reçues d’ici le 31 décembre 2026.' },
