    'about.hero.tag': { en: 'About us', fr: 'À propos' },
    'about.hero.title': { en: 'The story behind Magicstick Clean', fr: 'L’histoire derrière Magicstick Clean' },
    'about.hero.lede': { en: 'Locally owned and run by hand, not by a call center: when you book with us, a real person answers the same day.', fr: 'Une entreprise locale, gérée à la main, pas par un centre d’appels : quand vous réservez avec nous, une vraie personne vous répond le jour même.' },
    'about.story.title': { en: 'Why we started Magicstick Clean', fr: 'Pourquoi nous avons fondé Magicstick Clean' },
    'about.story.p1': { en: 'We started Magicstick Clean because we were tired of seeing cleaning done the impersonal way: a call center between you and the person in your home, and no one you could really reach if something wasn’t right.', fr: 'Nous avons fondé Magicstick Clean parce que nous en avions assez de voir le ménage fait de façon impersonnelle : un centre d’appels entre vous et la personne dans votre maison, et personne à joindre vraiment si quelque chose n’allait pas.' },
    'about.story.p2': { en: 'So we built something more personal: reliable cleaning you can count on, eco-friendly supplies we bring ourselves, and a direct line to the owner for anything you need, from Clarence-Rockland to Ottawa and across the river into Gatineau.', fr: 'Nous avons donc bâti quelque chose de plus personnel : un service fiable sur lequel compter, des produits écologiques que nous apportons nous-mêmes, et une ligne directe avec la propriétaire pour tout ce dont vous avez besoin, de Clarence-Rockland à Ottawa, jusqu’à Gatineau.' },
    'about.values.title': { en: 'What you can expect', fr: 'Ce à quoi vous attendre' },
    'about.values.item1': { en: 'Detail-oriented and reliable, every visit', fr: 'Minutieuse et fiable, à chaque visite' },
    'about.values.item2': { en: 'Flexible scheduling around your life', fr: 'Horaire flexible qui s’adapte à votre vie' },
    'about.values.item3': { en: 'Eco-friendly supplies, brought by us', fr: 'Produits écologiques, apportés par nous' },
    'about.values.item4': { en: 'Locally owned and operated', fr: 'Propriété locale et gestion locale' },
    'about.values.item5': { en: 'Not happy? We’ll come back and make it right, free', fr: 'Pas satisfait? Nous revenons tout arranger, gratuitement' },
    'about.values.careersLink': { en: 'As the business grows, so does the team, interested in joining? <a href="careers.html">See open positions &rarr;</a>', fr: "L'entreprise grandit, l'équipe aussi, intéressé(e) à te joindre? <a href=\"careers.html\">Voir les postes ouverts &rarr;</a>" },
    'about.cta.title': { en: 'Ready to see the difference?', fr: 'Prêt à voir la différence?' },
    'about.cta.desc': { en: 'Request a free quote, or book your first cleaning online.', fr: 'Demandez un devis gratuit, ou réservez votre premier ménage en ligne.' },
    'about.cta.quote': { en: 'Get a quote', fr: 'Demander un devis' },
    'about.cta.book': { en: 'Book online', fr: 'Réserver en ligne' },

    'giftcards.hero.tag': { en: 'Gift cards', fr: 'Cartes-cadeaux' },
    'giftcards.hero.title': { en: 'Give the gift of a clean home', fr: 'Offrez le cadeau d’une maison propre' },
    'giftcards.hero.lede': { en: 'A Magicstick Clean gift card is perfect for a housewarming, a new parent, a birthday, or just because. Request one online in a minute: we confirm within a day, you pay by Interac e-transfer, and the card arrives by email with its own code.', fr: 'Une carte-cadeau Magicstick Clean est parfaite pour une pendaison de crémaillère, de nouveaux parents, un anniversaire, ou simplement pour faire plaisir. Demandez-la en ligne en une minute : nous confirmons en moins d’une journée, vous payez par virement Interac, et la carte arrive par courriel avec son propre code.' },
